async function saveDatabase(database: Database): Promise<void> {
  const directory = dirname(file);
  const temporary = join(directory, `.${basename(file)}.${process.pid}.${crypto.randomUUID()}.tmp`);
  try {
    await Bun.write(temporary, `${JSON.stringify(database, null, 2)}\n`);
    await Bun.file(temporary).exists() || fail("cannot write database");
    await import("node:fs/promises").then(({ rename }) => rename(temporary, file));
  } catch (error) {
    try { await import("node:fs/promises").then(({ unlink }) => unlink(temporary)); } catch {}
    fail(`cannot write database: ${(error as Error).message}`);
  }
}

function parseFlags(args: string[], allowed: Set<string>): Map<string, string> {
  const flags = new Map<string, string>();
  for (let index = 0; index < args.length; index += 2) {
    const flag = args[index];
    if (!flag?.startsWith("--") || !allowed.has(flag)) fail(`unknown flag: ${flag ?? ""}`);
    if (flags.has(flag)) fail(`duplicate flag: ${flag}`);
    const value = args[index + 1];
    if (value === undefined || value.startsWith("--")) fail(`missing value for ${flag}`);
    flags.set(flag, value);
  }
  return flags;
}

function parseId(value: string | undefined): number {
  if (value === undefined || !/^[1-9]\d*$/.test(value)) fail("ID must be a positive integer");
  const id = Number(value);
  if (!Number.isSafeInteger(id)) fail("ID must be a positive integer");
  return id;
}

function normalizeTag(tag: string): string {
  return tag.trim().toLowerCase();
}

function localToday(): string {
  const date = new Date();
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

async function main(args: string[]): Promise<unknown> {
  const [command, ...rest] = args;
  if (!command) fail("missing command");

  if (command === "add") {
    const flags = parseFlags(rest, new Set(["--title", "--tags", "--due"]));
    const title = flags.get("--title")?.trim();
    if (!title) fail("--title is required and must not be empty");
    const due = flags.get("--due");
    if (due !== undefined && !validDate(due)) fail("--due must be a valid YYYY-MM-DD date");
    const tags = flags.has("--tags")
      ? [...new Set(flags.get("--tags")!.split(",").map(normalizeTag).filter(Boolean))]
      : [];
    const database = await loadDatabase();
    const task: Task = { id: database.nextId++, title, status: "open", createdAt: new Date().toISOString(), tags };
    if (due !== undefined) task.due = due;
    database.tasks.push(task);
    await saveDatabase(database);
    return task;
  }

  if (command === "list") {
    const flags = parseFlags(rest, new Set(["--status", "--tag", "--overdue"]));
    const status = flags.get("--status");
    if (status !== undefined && status !== "open" && status !== "done") fail("--status must be open or done");
    const tag = flags.get("--tag");
    if (tag !== undefined && normalizeTag(tag) === "") fail("--tag must not be empty");
    const overdue = flags.get("--overdue");
    if (overdue !== undefined && !validDate(overdue)) fail("--overdue must be a valid YYYY-MM-DD date");
    const database = await loadDatabase();
    return database.tasks
      .filter((task) => status === undefined || task.status === status)
      .filter((task) => tag === undefined || task.tags.includes(normalizeTag(tag)))
      .filter((task) => overdue === undefined || (task.status === "open" && task.due !== undefined && task.due < overdue))
      .sort((a, b) => a.id - b.id);
  }

  if (command === "done") {
    if (rest.length !== 1) fail(rest.length > 1 ? `unknown argument: ${rest[1]}` : "missing task ID");
    const id = parseId(rest[0]);
    const database = await loadDatabase();
    const task = database.tasks.find((item) => item.id === id);
    if (!task) fail(`task ${id} not found`);
    if (task.status === "open") {
      task.status = "done";
      task.completedAt = new Date().toISOString();
      await saveDatabase(database);
    }
    return task;
  }

  if (command === "delete") {
    if (rest.length !== 1) fail(rest.length > 1 ? `unknown argument: ${rest[1]}` : "missing task ID");
    const id = parseId(rest[0]);
    const database = await loadDatabase();
    const index = database.tasks.findIndex((item) => item.id === id);
    if (index < 0) fail(`task ${id} not found`);
    const [task] = database.tasks.splice(index, 1);
    await saveDatabase(database);
    return task;
  }

  if (command === "stats") {
    if (rest.length) fail(`unknown argument: ${rest[0]}`);
    const database = await loadDatabase();
    const today = localToday();
    return {
      total: database.tasks.length,
      open: database.tasks.filter((task) => task.status === "open").length,
      done: database.tasks.filter((task) => task.status === "done").length,
      overdue: database.tasks.filter((task) => task.status === "open" && task.due !== undefined && task.due < today).length,
    };
  }

  fail(`unknown command: ${command}`);
}

try {
  const result = await main(process.argv.slice(2));
  console.log(JSON.stringify(result));
} catch (error) {
  console.error(error instanceof CliError ? error.message : `unexpected error: ${(error as Error).message}`);
  process.exitCode = 1;
}
